INSERT INTO items VALUES (379, 'tm75', 1000, 0, 'all-machines', 'A frenetic dance to uplift the fighting spirit. It sharply raises the user’s Attack stat.');
INSERT INTO items VALUES (380, 'tm76', 10000, 0, 'all-machines', 'The user lays a trap of levitating stones around the foe. The trap hurts foes that switch into battle.');
INSERT INTO items VALUES (381, 'tm77', 1000, 0, 'all-machines', 'The user hypnotizes itself into copying any stat change made by the foe.');
INSERT INTO items VALUES (382, 'tm78', 1000, 0, 'all-machines', 'If it is the opposite gender of the user, the foe is charmed into sharply lowering its Sp. Atk stat.');
INSERT INTO items VALUES (383, 'tm79', 1000, 0, 'all-machines', 'The user releases a horrible aura imbued with dark thoughts. It may also make the target flinch.');
INSERT INTO items VALUES (384, 'tm80', 1000, 0, 'all-machines', 'Large boulders are hurled at the foe to inflict damage. It may also make the target flinch.');
INSERT INTO items VALUES (385, 'tm81', 1000, 0, 'all-machines', 'The user slashes at the foe by crossing its scythes or claws as if they were a pair of scissors.');
INSERT INTO items VALUES (386, 'tm82', 1000, 0, 'all-machines', 'While it is asleep, the user randomly uses one of the moves it knows.');
INSERT INTO items VALUES (387, 'tm83', 100000, 0, 'all-machines', 'The user draws power from the Berry it is holding to attack. The Berry determines its type and power.');
INSERT INTO items VALUES (388, 'tm84', 1000, 0, 'all-machines', 'The foe is stabbed with a tentacle or arm seeped with poison. It may also poison the foe.');
INSERT INTO items VALUES (389, 'tm85', 1000, 0, 'all-machines', 'An attack that works only on a sleeping foe. It absorbs half the damage caused to heal the user’s HP.');
INSERT INTO items VALUES (390, 'tm86', 1000, 0, 'all-machines', 'The user snares the foe with grass and trips it. The heavier the foe, the greater the damage.');
INSERT INTO items VALUES (391, 'tm87', 1000, 0, 'all-machines', 'The user enrages the foe into confusion. However, it also sharply raises the foe’s Attack stat.');
INSERT INTO items VALUES (392, 'tm88', 20000, 0, 'all-machines', 'The user pecks the foe. If the foe is holding a Berry, the user plucks it and gains its effect.');
INSERT INTO items VALUES (393, 'tm89', 20000, 0, 'all-machines', 'After making its attack, the user rushes back to switch places with a party Pokémon in waiting.');
INSERT INTO items VALUES (394, 'tm90', 20000, 0, 'all-machines', 'The user makes a copy of itself using some of its HP. The copy serves as the user’s decoy.');
INSERT INTO items VALUES (395, 'tm91', 20000, 0, 'all-machines', 'The user gathers all its light energy and releases it in one shot. It may also lower the foe’s Sp. Def stat.');
INSERT INTO items VALUES (396, 'tm92', 100000, 0, 'all-machines', 'The user creates a bizarre space in which slower Pokémon get to move first for five turns.');
INSERT INTO items VALUES (397, 'hm01', 0, 0, 'all-machines', 'Attacks the foe with sharp blades or claws.');
INSERT INTO items VALUES (398, 'hm02', 0, 0, 'all-machines', 'Flies up on the first turn, then attacks next turn.');
INSERT INTO items VALUES (399, 'hm03', 0, 0, 'all-machines', 'Creates a huge wave, then crashes it down on the foe.');
INSERT INTO items VALUES (400, 'hm04', 0, 0, 'all-machines', 'Builds enormous power, then slams the foe.');
INSERT INTO items VALUES (401, 'hm05', 0, 0, 'all-machines', 'Looses a powerful blast of light that reduces accuracy.');
INSERT INTO items VALUES (402, 'hm06', 0, 0, 'all-machines', 'A rock-crushingly tough attack that may lower DEFENSE.');
INSERT INTO items VALUES (403, 'hm07', 0, 0, 'all-machines', 'Attacks the foe with enough power to climb waterfalls.');
INSERT INTO items VALUES (404, 'hm08', 0, 0, 'all-machines', 'Dives underwater the 1st turn, then attacks next turn.');
INSERT INTO items VALUES (405, 'explorer-kit', 0, 0, 'gameplay', 'A bag filled with convenient tools for exploring. It provides access to the Underground.');
INSERT INTO items VALUES (406, 'loot-sack', 0, 0, 'unused', 'A sturdy, spacious bag that is used to carry loot obtained in the coal mine.');
INSERT INTO items VALUES (407, 'rule-book', 0, 0, 'unused', 'It lists the rules for holding battles. For linked battles, you may choose which set of rules you wish to use.');
INSERT INTO items VALUES (408, 'poke-radar', 0, 0, 'gameplay', 'A tool that can search out Pokémon that are hiding in grass. Its battery is recharged as you walk.');
INSERT INTO items VALUES (409, 'point-card', 0, 0, 'gameplay', 'A card that lists the Battle Points you have earned. ');
INSERT INTO items VALUES (410, 'journal', 0, 0, 'gameplay', 'A notebook that keeps a day-to-day record of your adventure so far. ');
INSERT INTO items VALUES (411, 'seal-case', 0, 0, 'gameplay', 'A case for storing Seals that can be applied to the capsule cases of Poké Balls.');
INSERT INTO items VALUES (412, 'fashion-case', 0, 0, 'gameplay', 'A fancy case for the tidy and organized storage of colorful Pokémon Accessories.');
INSERT INTO items VALUES (413, 'seal-bag', 0, 0, 'unused', 'A tiny bag that can hold ten Seals for decorating Poké Balls.');
INSERT INTO items VALUES (414, 'pal-pad', 0, 0, 'gameplay', 'A convenient notepad that is used for registering your friends and keeping a record of game play.');
INSERT INTO items VALUES (415, 'works-key', 0, 0, 'plot-advancement', 'A large key for operating the doors of the Valley Windworks in the canyon. It was held by a Team Galactic Grunt.');
INSERT INTO items VALUES (416, 'old-charm', 0, 0, 'plot-advancement', 'An ancient good-luck charm made of Pokémon bones to be taken to the elder of Celestic Town.');
INSERT INTO items VALUES (417, 'galactic-key', 0, 0, 'plot-advancement', 'A card key for disengaging security systems in the Galactic HQ. Losing it can result in punishment, apparently.');
INSERT INTO items VALUES (418, 'red-chain', 0, 0, 'unused', 'A mythical chain that is said to link the legendary Pokémon that created the Sinnoh region.');
INSERT INTO items VALUES (419, 'town-map', 0, 0, 'gameplay', 'Can be viewed anytime. Shows your present location.');
INSERT INTO items VALUES (420, 'vs-seeker', 0, 0, 'gameplay', 'A rechargeable unit that flags battle- ready TRAINERS.');
INSERT INTO items VALUES (421, 'coin-case', 0, 0, 'gameplay', 'A case that holds up to 9,999 COINS.');
INSERT INTO items VALUES (422, 'old-rod', 0, 0, 'gameplay', 'Use by any body of water to fish for wild POKéMON.');
INSERT INTO items VALUES (423, 'good-rod', 0, 0, 'gameplay', 'A decent fishing rod for catching wild POKéMON.');
INSERT INTO items VALUES (424, 'super-rod', 0, 0, 'gameplay', 'The best fishing rod for catching wild POKéMON.');
INSERT INTO items VALUES (425, 'sprayduck', 0, 0, 'gameplay', 'A watering can shaped like a PSYDUCK. It helps promote healthy growth of Berries planted in soft soil.');
INSERT INTO items VALUES (426, 'poffin-case', 0, 0, 'gameplay', 'A case for storing Poffin cooked from Berries. ');
INSERT INTO items VALUES (427, 'bicycle', 0, 0, 'gameplay', 'A folding bicycle that is faster than the RUNNING SHOES.');
INSERT INTO items VALUES (428, 'suite-key', 0, 0, 'event-items', 'A key to one of the suites at the luxury hotel by a lake. For some odd reason, it often disappears.');
INSERT INTO items VALUES (429, 'oaks-letter', 0, 0, 'event-items', 'A letter from Prof. Oak. Written in it is a request for you to go to Rt. 224.');
INSERT INTO items VALUES (430, 'lunar-wing', 0, 0, 'event-items', 'A feather that glows like the moon. It is said to possess the power to dispel nightmares.');
INSERT INTO items VALUES (431, 'member-card', 0, 0, 'event-items', 'A card needed for entering the inn in Canalave City. Oddly, the last date marked on it was 50 years ago.');
INSERT INTO items VALUES (432, 'azure-flute', 0, 0, 'event-items', 'A flute that puts out echoing sounds that do not seem to be of this world. It is unknown who made it.');
INSERT INTO items VALUES (433, 'ss-ticket', 0, 0, 'plot-advancement', 'The ticket required for sailing on a ferry.');
INSERT INTO items VALUES (434, 'contest-pass', 0, 0, 'gameplay', 'The pass required for entering POKéMON CONTESTS.');
INSERT INTO items VALUES (435, 'magma-stone', 0, 0, 'plot-advancement', 'A stone formed when boulders melted in intensely hot magma, then hardened. Magma remains sealed inside.');
INSERT INTO items VALUES (436, 'parcel', 0, 0, 'plot-advancement', 'A parcel entrusted into your care. You’re supposed to deliver it to your childhood friend who left Twinleaf Town.');
INSERT INTO items VALUES (437, 'coupon-1', 0, 0, 'plot-advancement', 'A coupon to be exchanged for a Pokémon Watch (Pokétch for short). Three coupons are needed.');
INSERT INTO items VALUES (438, 'coupon-2', 0, 0, 'plot-advancement', 'A coupon to be exchanged for a Pokémon Watch (Pokétch for short). Three coupons are needed.');
INSERT INTO items VALUES (439, 'coupon-3', 0, 0, 'plot-advancement', 'A coupon to be exchanged for a Pokémon Watch (Pokétch for short). Three coupons are needed.');
INSERT INTO items VALUES (440, 'storage-key', 0, 0, 'plot-advancement', 'The key to the storage inside the ABANDONED SHIP.');
INSERT INTO items VALUES (441, 'secret-potion', 0, 0, 'plot-advancement', 'A fantastic medicine dispensed by the pharmacy in Cianwood City. It fully heals a Pokémon of any ailment.');
INSERT INTO items VALUES (442, 'griseous-orb', 0, 60, 'species-specific', 'A glowing orb to be held by GIRATINA. It boosts the power of Dragon- and Ghost-type moves.');
INSERT INTO items VALUES (443, 'vs-recorder', 0, 0, 'gameplay', 'An amazing device that can record a battle either between friends or at a special battle facility.');
INSERT INTO items VALUES (444, 'gracidea', 0, 0, 'event-items', 'A flower sometimes bundled in bouquets to convey gratitude on special occasions like birthdays.');
INSERT INTO items VALUES (445, 'secret-key', 0, 0, 'event-items', 'The key to the CINNABAR ISLAND GYM’s entrance.');
INSERT INTO items VALUES (446, 'apricorn-box', 0, 0, 'gameplay', 'A handy box where you can store up to 99 Apricorns of each kind.');
INSERT INTO items VALUES (447, 'berry-pots', 0, 0, 'gameplay', 'Handy containers for cultivating Berries wherever you go.');
INSERT INTO items VALUES (448, 'squirt-bottle', 0, 0, 'plot-advancement', 'A bottle used for watering plants in the Berry Pots.');
