INSERT INTO items VALUES (450, 'level-ball', 0, 0, 'apricorn-balls', 'A Poké Ball for catching Pokémon that are a lower level than your own.');
INSERT INTO items VALUES (451, 'moon-ball', 0, 0, 'apricorn-balls', 'A Poké Ball for catching Pokémon that evolve using the Moon Stone.');
INSERT INTO items VALUES (452, 'heavy-ball', 0, 0, 'apricorn-balls', 'A Poké Ball for catching very heavy Pokémon.');
INSERT INTO items VALUES (453, 'fast-ball', 0, 0, 'apricorn-balls', 'A Poké Ball that makes it easier to catch fast Pokémon.');
