INSERT INTO items VALUES (459, 'blue-apricorn', 200, 10, 'apricorn-box', 'A blue Apricorn. It smells a bit like grass.');
INSERT INTO items VALUES (460, 'yellow-apricorn', 200, 10, 'apricorn-box', 'A yellow Apricorn. It has an invigorating scent.');
INSERT INTO items VALUES (461, 'green-apricorn', 200, 10, 'apricorn-box', 'A green Apricorn. It has a mysterious, aromatic scent.');
INSERT INTO items VALUES (462, 'pink-apricorn', 200, 10, 'apricorn-box', 'A pink Apricorn. It has a nice, sweet scent.');
INSERT INTO items VALUES (463, 'white-apricorn', 200, 10, 'apricorn-box', 'A white Apricorn. It doesn’t smell like anything.');
INSERT INTO items VALUES (464, 'black-apricorn', 200, 10, 'apricorn-box', 'A black Apricorn It has an indescribable scent.');
