INSERT INTO items VALUES (580, 'prism-scale', 2000, 30, 'evolution', 'A mysterious scale that evolves certain Pokémon. It shines in rainbow colors.');
INSERT INTO items VALUES (581, 'eviolite', 4000, 40, 'held-items', 'A mysterious evolutionary lump. When held, it raises the Defense and Sp. Def of a Pokémon that can still evolve.');
