INSERT INTO items VALUES (728, 'lumiose-galette', 350, 30, 'status-cures', 'A popular treat in Lumiose City. It can be used once to heal all the status conditions of a Pokémon.');
INSERT INTO items VALUES (729, 'jaw-fossil', 7000, 100, 'dex-completion', 'A fossil from a prehistoric Pokémon that once lived on the land. It looks as if it could be a piece of a large jaw.');
INSERT INTO items VALUES (730, 'sail-fossil', 7000, 100, 'dex-completion', 'A fossil from a prehistoric Pokémon that once lived on the land. It looks like the impression from a skin sail.');
INSERT INTO items VALUES (731, 'fairy-gem', 200, 0, 'jewels', 'A gem with an essence of the fey. When held, it strengthens the power of a Fairy-type move one time.');
INSERT INTO items VALUES (732, 'adventure-rules', 0, 0, 'gameplay', 'This book contains all the points a new Trainer needs to know on a journey. It was handmade by a kind friend.');
INSERT INTO items VALUES (733, 'elevator-key', 0, 0, 'plot-advancement', 'A card key that activates the elevator in Lysandre Labs. It is emblazoned with Team Flare’s logo.');
INSERT INTO items VALUES (734, 'holo-caster', 0, 0, 'gameplay', 'A device that allows users to receive and view hologram clips at any time. It is also used to chat with others.');
INSERT INTO items VALUES (735, 'honor-of-kalos', 0, 0, 'plot-advancement', 'A precious symbol that is awarded only to an individual who has done great things for the Kalos region.');
INSERT INTO items VALUES (736, 'intriguing-stone', 0, 0, 'plot-advancement', 'A rather curious stone that might appear to be valuable to some. It’s all in the eye of the beholder.');
INSERT INTO items VALUES (737, 'lens-case', 0, 0, 'gameplay', 'A rather chic-looking case for carrying contact lenses.');
INSERT INTO items VALUES (738, 'looker-ticket', 0, 0, 'plot-advancement', 'A ticket that was handmade by Looker. It’s decorated with a liberal amount of glittery paint.');
INSERT INTO items VALUES (739, 'mega-ring', 0, 0, 'gameplay', 'This ring contains an untold power that somehow enables Pokémon carrying Mega Stones to Mega Evolve in battle.');
INSERT INTO items VALUES (740, 'power-plant-pass', 0, 0, 'plot-advancement', 'This pass serves as an ID card for gaining access to the power plant that lies along Route 13.');
INSERT INTO items VALUES (741, 'profs-letter', 0, 0, 'plot-advancement', 'A letter that Professor Sycamore wrote to your mother. A faint but pleasant perfume seems to cling to the paper.');
INSERT INTO items VALUES (742, 'roller-skates', 0, 0, 'gameplay', 'Attaches roller skates to the bottom of your shoes, allowing you to glide quickly around and perform tricks.');
INSERT INTO items VALUES (743, 'sprinklotad', 0, 0, 'gameplay', 'A watering can shaped like a Lotad. It helps promote the healthy growth of any Berries planted in good, soft soil.');
INSERT INTO items VALUES (744, 'tmv-pass', 0, 0, 'gameplay', 'A commuter pass that allows the holder to ride the TMV between Lumiose City and Kiloude City at any time.');
INSERT INTO items VALUES (745, 'tm96', 1000, 0, 'all-machines', 'An attack that makes use of nature’s power. Its effects vary depending on the user’s environment.');
INSERT INTO items VALUES (746, 'tm97', 1000, 0, 'all-machines', 'The user releases a horrible aura imbued with dark thoughts. This may also make the target flinch.');
INSERT INTO items VALUES (747, 'tm98', 1000, 0, 'all-machines', 'Striking opponents over and over makes the user’s fists harder. Hitting a target raises the Attack stat.');
INSERT INTO items VALUES (748, 'tm99', 1000, 0, 'all-machines', 'The user damages opposing Pokémon by emitting a powerful flash.');
INSERT INTO items VALUES (749, 'tm100', 5000, 0, 'all-machines', 'The user tells the target a secret, and the target loses its ability to concentrate. This lowers the target’s Sp. Atk stat.');
INSERT INTO items VALUES (760, 'latiasite', 0, 80, 'mega-stones', 'One of a variety of mysterious Mega Stones. Have Latias hold it, and this stone will enable it to Mega Evolve during battle.');
INSERT INTO items VALUES (761, 'latiosite', 0, 80, 'mega-stones', 'One of a variety of mysterious Mega Stones. Have Latios hold it, and this stone will enable it to Mega Evolve during battle.');
INSERT INTO items VALUES (762, 'common-stone', 0, 0, 'unused', 'A perfectly normal stone that might appear to be valuable to some. It’s all in the eye of the beholder.');
INSERT INTO items VALUES (763, 'makeup-bag', 0, 0, 'gameplay', 'A rather chic-looking case for carrying lipsticks.');
INSERT INTO items VALUES (764, 'travel-trunk', 0, 0, 'unused', 'A light and yet incredibly effective trunk, which can contain every last piece of clothing that can be bought.');
INSERT INTO items VALUES (765, 'shalour-sable', 350, 30, 'status-cures', 'Shalour City’s famous shortbread. It can be used once to heal all the status conditions of a Pokémon.');
INSERT INTO items VALUES (768, 'mega-charm', 0, 0, 'unused', 'This charm contains an untold power that somehow enables Pokémon carrying Mega Stones to Mega Evolve in battle.');
INSERT INTO items VALUES (769, 'mega-glove', 0, 0, 'unused', 'This glove contains an untold power that somehow enables Pokémon carrying Mega Stones to Mega Evolve in battle.');
INSERT INTO items VALUES (770, 'devon-parts', 0, 0, 'plot-advancement', 'A case that contains mechanical parts of some sort made by the Devon Corporation.');
INSERT INTO items VALUES (772, 'pokeblock-kit', 0, 0, 'gameplay', 'A set containing a Berry Blender for making Pokéblocks and a Pokéblock Case for storing Pokéblocks.');
INSERT INTO items VALUES (773, 'key-to-room-1', 0, 0, 'plot-advancement', 'A key that opens a door inside Sea Mauville.');
INSERT INTO items VALUES (774, 'key-to-room-2', 0, 0, 'plot-advancement', 'A key that opens a door inside Sea Mauville.');
INSERT INTO items VALUES (775, 'key-to-room-4', 0, 0, 'plot-advancement', 'A key that opens a door inside Sea Mauville.');
INSERT INTO items VALUES (776, 'key-to-room-6', 0, 0, 'plot-advancement', 'A key that opens a door inside Sea Mauville.');
INSERT INTO items VALUES (779, 'devon-scuba-gear', 0, 0, 'plot-advancement', 'A device made by Devon Corporation that provides oxygen to users during the use of Dive.');
INSERT INTO items VALUES (780, 'contest-costume--jacket', 0, 0, 'gameplay', 'A very cool suit to be worn during the Contest Spectacular.');
INSERT INTO items VALUES (782, 'magma-suit', 0, 0, 'plot-advancement', 'A suit made with the collective technological know-how of Team Magma. It can withstand any impact.');
INSERT INTO items VALUES (783, 'aqua-suit', 0, 0, 'plot-advancement', 'A suit made with the collective technological know-how of Team Aqua. It can withstand any impact.');
INSERT INTO items VALUES (784, 'pair-of-tickets', 0, 0, 'plot-advancement', 'Tickets for two to the astronomical show being held at the Mossdeep Space Center.');
INSERT INTO items VALUES (785, 'mega-bracelet', 0, 0, 'gameplay', 'This cuff contains an untold power that somehow enables Pokémon carrying a Mega Stone to Mega Evolve in battle.');
INSERT INTO items VALUES (786, 'mega-pendant', 0, 0, 'unused', 'This necklace contains an untold power that somehow enables Pokémon carrying a Mega Stone to Mega Evolve in battle.');
INSERT INTO items VALUES (787, 'mega-glasses', 0, 0, 'unused', 'These glasses contain an untold power that somehow enables Pokémon carrying a Mega Stone to Mega Evolve in battle.');
