INSERT INTO items VALUES (811, 'beedrillite', 0, 80, 'mega-stones', 'One of a variety of mysterious Mega Stones. Have Beedrill hold it, and this stone will enable it to Mega Evolve during battle.');
INSERT INTO items VALUES (814, 'key-stone', 0, 0, 'gameplay', 'A stone filled with an unexplained power. It makes Pokémon that battle with a Mega Stone Mega Evolve.');
INSERT INTO items VALUES (815, 'meteorite-shard', 0, 0, 'plot-advancement', 'One of the fragments of a Meteorite from Granite Cave. It’s faintly warm to the touch.');
INSERT INTO items VALUES (816, 'eon-flute', 0, 0, 'gameplay', 'A flute that can be used to summon Latios or Latias no matter where you are.');
