INSERT INTO items VALUES (835, 'pikanium-z--held', 0, 0, 'z-crystals', 'This is a crystallized form of Z-Power. It upgrades Pikachu’s Volt Tackle to a Z-Move.');
INSERT INTO items VALUES (836, 'bottle-cap', 5000, 30, 'loot', 'A beautiful bottle cap that gives off a silver gleam. Some people are happy to receive one.');
INSERT INTO items VALUES (837, 'gold-bottle-cap', 10000, 30, 'loot', 'A beautiful bottle cap that gives off a golden gleam. Some people are happy to receive one.');
INSERT INTO items VALUES (838, 'z-ring', 0, 0, 'gameplay', 'A mysterious ring that enables Pokémon to use Z-Power. It requires both the willpower and the physical power of the Trainer wearing it.');
INSERT INTO items VALUES (839, 'decidium-z--held', 0, 0, 'z-crystals', 'This is a crystallized form of Z-Power. It upgrades Decidueye’s Spirit Shackle to a Z-Move.');
INSERT INTO items VALUES (840, 'incinium-z--held', 0, 0, 'z-crystals', 'This is a crystallized form of Z-Power. It upgrades Incineroar’s Darkest Lariat to a Z-Move.');
INSERT INTO items VALUES (841, 'primarium-z--held', 0, 0, 'z-crystals', 'This is a crystallized form of Z-Power. It upgrades Primarina’s Sparkling Aria to a Z-Move.');
INSERT INTO items VALUES (842, 'tapunium-z--held', 0, 0, 'z-crystals', 'This is a crystallized form of Z-Power. It upgrades the tapu’s Nature’s Madness to a Z-Move.');
INSERT INTO items VALUES (843, 'marshadium-z--held', 0, 0, 'z-crystals', 'This is a crystallized form of Z-Power. It upgrades Marshadow’s Spectral Thief to a Z-Move.');
INSERT INTO items VALUES (844, 'aloraichium-z--held', 0, 0, 'z-crystals', 'This is a crystallized form of Z-Power. It upgrades Alolan Raichu’s Thunderbolt to a Z-Move.');
INSERT INTO items VALUES (845, 'snorlium-z--held', 0, 0, 'z-crystals', 'This is a crystallized form of Z-Power. It upgrades Snorlax’s Giga Impact to a Z-Move.');
INSERT INTO items VALUES (846, 'eevium-z--held', 0, 0, 'z-crystals', 'This is a crystallized form of Z-Power. It upgrades Eevee’s Last Resort to a Z-Move.');
INSERT INTO items VALUES (847, 'mewnium-z--held', 0, 0, 'z-crystals', 'This is a crystallized form of Z-Power. It upgrades Mew’s Psychic to a Z-Move.');
INSERT INTO items VALUES (877, 'pikashunium-z--held', 0, 0, 'z-crystals', 'This is a crystallized form of Z-Power. It upgrades a Thunderbolt by Pikachu in a cap to a Z-Move.');
INSERT INTO items VALUES (878, 'forage-bag', 0, 0, 'gameplay', 'A bag to carry ingredients gathered during Mallow’s trial in the jungle.');
INSERT INTO items VALUES (879, 'fishing-rod', 0, 0, 'gameplay', 'A Fishing Rod made by Captain Lana. Cast a line over piles of underwater rocks to fish for wild aquatic Pokémon.');
INSERT INTO items VALUES (880, 'professors-mask', 0, 0, 'plot-advancement', 'The mask that belongs to The Masked Royal.  This pro wrestler apparently sews his mask on a machine himself.');
INSERT INTO items VALUES (881, 'festival-ticket', 10, 0, 'gameplay', 'A ticket that allows you to host a mission in Festival Plaza.');
INSERT INTO items VALUES (882, 'sparkling-stone', 0, 0, 'plot-advancement', 'A stone entrusted by a Pokémon that has been venerated as a guardian deity in the Alola region. There is said to be some secret in how it sparkles.');
INSERT INTO items VALUES (883, 'adrenaline-orb', 4000, 30, 'held-items', 'Using it makes wild Pokémon more likely to call for help. If held by a Pokémon, it boosts Speed when intimidated. It can be used only once.');
INSERT INTO items VALUES (884, 'zygarde-cube', 0, 0, 'gameplay', 'An item to store Zygarde Cores and Cells. You can also use it to teach Zygarde moves.');
INSERT INTO items VALUES (885, 'ice-stone', 3000, 30, 'evolution', 'A peculiar stone that can make certain species of Pokémon evolve. It has an unmistakable snowflake pattern.');
INSERT INTO items VALUES (886, 'ride-pager', 0, 0, 'unused', 'By entering certain numbers on this pager, you can summon Ride Pokémon in an instant.');
INSERT INTO items VALUES (887, 'beast-ball', 0, 0, 'special-balls', 'A special Poké Ball designed to catch Ultra Beasts. It has a low success rate for catching others.');
INSERT INTO items VALUES (888, 'big-malasada', 350, 30, 'status-cures', 'The Alola region’s local specialty—fried bread. It can be used once to heal all the status conditions of a Pokémon.');
INSERT INTO items VALUES (889, 'red-nectar', 300, 10, 'species-specific', 'A flower nectar obtained at Ula’ula Meadow. It changes the form of certain species of Pokémon.');
INSERT INTO items VALUES (890, 'yellow-nectar', 300, 10, 'species-specific', 'A flower nectar obtained at Melemele Meadow. It changes the form of certain species of Pokémon.');
INSERT INTO items VALUES (891, 'pink-nectar', 300, 10, 'species-specific', 'The flower nectar obtained at the flowering shrubs on Royal Avenue. It changes the form of certain species of Pokémon.');
INSERT INTO items VALUES (892, 'purple-nectar', 300, 10, 'species-specific', 'A flower nectar obtained at Poni Meadow. It changes the form of certain species of Pokémon.');
INSERT INTO items VALUES (893, 'sun-flute', 0, 0, 'plot-advancement', 'It is said that the tones it produces were offered up as an expression of gratitude to the Legendary Pokémon of the sun.');
INSERT INTO items VALUES (894, 'moon-flute', 0, 0, 'plot-advancement', 'It is said that the tones it produces were offered up as an expression of gratitude to the Legendary Pokémon of the moon.');
INSERT INTO items VALUES (895, 'enigmatic-card', 0, 0, 'plot-advancement', 'A mysterious card. Written on it is a request for you to go to a guest room in an Akala motel on Route 8.');
INSERT INTO items VALUES (896, 'terrain-extender', 4000, 60, 'held-items', 'An item to be held by a Pokémon. It extends the duration of the terrain caused by the holder’s move or Ability.');
INSERT INTO items VALUES (897, 'protective-pads', 4000, 30, 'held-items', 'An item to be held by a Pokémon. These pads protect the holder from effects caused by making direct contact with the target.');
INSERT INTO items VALUES (898, 'electric-seed', 4000, 10, 'held-items', 'An item to be held by a Pokémon. It boosts Defense on Electric Terrain. It can only be used once.');
INSERT INTO items VALUES (899, 'psychic-seed', 4000, 10, 'held-items', 'An item to be held by a Pokémon. It boosts Sp. Def on Psychic Terrain. It can only be used once.');
INSERT INTO items VALUES (900, 'misty-seed', 4000, 10, 'held-items', 'An item to be held by a Pokémon. It boosts Sp. Def on Misty Terrain. It can only be used once.');
INSERT INTO items VALUES (901, 'grassy-seed', 4000, 10, 'held-items', 'An item to be held by a Pokémon. It boosts Defense on Grassy Terrain. It can only be used once.');
