INSERT INTO items VALUES (919, 'bike--green', 0, 0, 'unused', 'A folding Bike that enables a rider to get around much faster than with Running Shoes.');
INSERT INTO items VALUES (920, 'storage-key--galactic-warehouse', 0, 0, 'unused', 'The key to Team Galactic’s sinister warehouse located at the edge of Veilstone City.');
INSERT INTO items VALUES (921, 'basement-key--goldenrod', 0, 0, 'unused', 'A key that opens a door in the Goldenrod Tunnel.');
INSERT INTO items VALUES (922, 'xtransceiver--red', 0, 0, 'unused', 'A high-tech transceiver with a camera function. It allows up to four-way calls.');
INSERT INTO items VALUES (923, 'xtransceiver--yellow', 0, 0, 'unused', 'A high-tech transceiver with a camera function. It allows up to four-way calls.');
INSERT INTO items VALUES (924, 'dna-splicers--merge', 0, 0, 'unused', 'A splicer that fuses Kyurem and a certain Pokémon. They are said to have been one in the beginning.');
INSERT INTO items VALUES (925, 'dna-splicers--split', 0, 0, 'unused', 'A splicer that separates Kyurem and a certain Pokémon when they have been fused.');
INSERT INTO items VALUES (926, 'dropped-item--red', 0, 0, 'unused', 'The Xtransceiver found at the Nimbasa City amusement park. It seems it belongs to a boy.');
INSERT INTO items VALUES (927, 'dropped-item--yellow', 0, 0, 'unused', 'The Xtransceiver found at the Nimbasa City amusement park. It seems it belongs to a girl.');
INSERT INTO items VALUES (928, 'holo-caster--green', 0, 0, 'unused', 'A device that allows users to receive and view hologram clips at any time. It’s also used to chat with others.');
INSERT INTO items VALUES (929, 'bike--yellow', 0, 0, 'unused', 'A folding bike that enables a rider to get around much faster than with Running Shoes.');
INSERT INTO items VALUES (930, 'holo-caster--red', 0, 0, 'unused', 'A device that allows users to receive and view hologram clips at any time. It’s also used to chat with others.');
INSERT INTO items VALUES (931, 'basement-key--new-mauville', 0, 0, 'unused', 'The key to New Mauville, which was constructed beneath Mauville City.');
INSERT INTO items VALUES (932, 'storage-key--sea-mauville', 0, 0, 'unused', 'A key that opens the storage hold inside Sea Mauville.');
INSERT INTO items VALUES (933, 'ss-ticket--hoenn', 0, 0, 'unused', 'Ticket required for sailing on a ferry.');
INSERT INTO items VALUES (934, 'contest-costume--dress', 0, 0, 'unused', 'A very cute dress to be worn during the Contest Spectacular.');
INSERT INTO items VALUES (935, 'meteorite--2', 0, 0, 'unused', 'A Meteorite that you got at Mt. Chimney. It gives off a faint glow.');
INSERT INTO items VALUES (936, 'meteorite--3', 0, 0, 'unused', 'A Meteorite that you got at Mt. Chimney. It continues to give off a faint glow and is slightly warm to the touch.');
INSERT INTO items VALUES (937, 'meteorite--4', 0, 0, 'unused', 'A Meteorite that you got at Mt. Chimney. Some sort of pattern has risen to the surface, and it’s shining with seven colors of light.');
