INSERT INTO items VALUES (956, 'pikanium-z--bag', 0, 0, 'unused', 'It converts Z-Power into crystals that upgrade Pikachu’s Volt Tackle to an exclusive Z-Move.');
INSERT INTO items VALUES (957, 'decidium-z--bag', 0, 0, 'unused', 'It converts Z-Power into crystals that upgrade Decidueye’s Spirit Shackle to an exclusive Z-Move.');
