INSERT INTO items VALUES (959, 'primarium-z--bag', 0, 0, 'unused', 'It converts Z-Power into crystals that upgrade Primarina’s Sparkling Aria to an exclusive Z-Move.');
INSERT INTO items VALUES (960, 'tapunium-z--bag', 0, 0, 'unused', 'It converts Z-Power into crystals that upgrade the tapu’s Nature’s Madness to an exclusive Z-Move.');
INSERT INTO items VALUES (961, 'marshadium-z--bag', 0, 0, 'unused', 'It converts Z-Power into crystals that upgrade Marshadow’s Spectral Thief to an exclusive Z-Move.');
INSERT INTO items VALUES (962, 'aloraichium-z--bag', 0, 0, 'unused', 'It converts Z-Power into crystals that upgrade Alolan Raichu’s Thunderbolt to an exclusive Z-Move.');
INSERT INTO items VALUES (963, 'snorlium-z--bag', 0, 0, 'unused', 'It converts Z-Power into crystals that upgrade Snorlax’s Giga Impact to an exclusive Z-Move.');
INSERT INTO items VALUES (964, 'eevium-z--bag', 0, 0, 'unused', 'It converts Z-Power into crystals that upgrade Eevee’s Last Resort to an exclusive Z-Move.');
INSERT INTO items VALUES (965, 'mewnium-z--bag', 0, 0, 'unused', 'It converts Z-Power into crystals that upgrade Mew’s Psychic to an exclusive Z-Move.');
INSERT INTO items VALUES (966, 'pikashunium-z--bag', 0, 0, 'unused', 'It converts Z-Power into crystals that upgrade a Thunderbolt by Pikachu in a cap to an exclusive Z-Move.');
INSERT INTO items VALUES (967, 'solganium-z--held', 0, 0, 'unused', 'This is a crystallized form of Z-Power. It upgrades Solgaleo’s Sunsteel Strike to a Z-Move.');
INSERT INTO items VALUES (968, 'lunalium-z--held', 0, 0, 'unused', 'This is a crystallized form of Z-Power. It upgrades Lunala’s Moongeist Beam to a Z-Move.');
INSERT INTO items VALUES (969, 'ultranecrozium-z--held', 0, 0, 'unused', 'This is a crystallized form of Z-Power. It upgrades Necrozma’s Photon Geyser to a Z-Move.');
INSERT INTO items VALUES (970, 'mimikium-z--held', 0, 0, 'unused', 'This is a crystallized form of Z-Power. It upgrades Mimikyu’s Play Rough to a Z-Move.');
INSERT INTO items VALUES (971, 'lycanium-z--held', 0, 0, 'unused', 'This is a crystallized form of Z-Power. It upgrades Lycanroc’s Stone Edge to a Z-Move.');
INSERT INTO items VALUES (972, 'kommonium-z--held', 0, 0, 'unused', 'This is a crystallized form of Z-Power. It upgrades Kommo-o’s Clanging Scales to a Z-Move.');
INSERT INTO items VALUES (973, 'solganium-z--bag', 0, 0, 'unused', 'It converts Z-Power into crystals that upgrade Solgaleo’s Sunsteel Strike to an exclusive Z-Move.');
INSERT INTO items VALUES (974, 'lunalium-z--bag', 0, 0, 'unused', 'It converts Z-Power into crystals that upgrade Lunala’s Moongeist Beam to an exclusive Z-Move.');
INSERT INTO items VALUES (975, 'ultranecrozium-z--bag', 0, 0, 'unused', 'It’s a crystal that turns Necrozma fused with Solgaleo or Lunala into a new form.');
INSERT INTO items VALUES (976, 'mimikium-z--bag', 0, 0, 'unused', 'It converts Z-Power into crystals that upgrade Mimikyu’s Play Rough to an exclusive Z-Move.');
INSERT INTO items VALUES (977, 'lycanium-z--bag', 0, 0, 'unused', 'It converts Z-Power into crystals that upgrade Lycanroc’s Stone Edge to an exclusive Z-Move.');
INSERT INTO items VALUES (978, 'kommonium-z--bag', 0, 0, 'unused', 'It converts Z-Power into crystals that upgrade Kommo-o’s Clanging Scales to an exclusive Z-Move.');
INSERT INTO items VALUES (979, 'z-power-ring', 0, 0, 'unused', 'A mysterious ring that enables Pokémon to use Z-Power. It requires both the willpower and the physical power of the Trainer wearing it.');
INSERT INTO items VALUES (980, 'pink-petal', 0, 0, 'unused', 'A pressed flower petal you receive from Mina during Mina’s trial. The goal is to collect seven different kinds of petals.');
INSERT INTO items VALUES (981, 'orange-petal', 0, 0, 'unused', 'A pressed flower petal you receive from Ilima during Mina’s trial. The goal is to collect seven different kinds of petals.');
INSERT INTO items VALUES (982, 'blue-petal', 0, 0, 'unused', 'A pressed flower petal you receive from Lana  during Mina’s trial. The goal is to collect seven different kinds of petals.');
INSERT INTO items VALUES (983, 'red-petal', 0, 0, 'unused', 'A pressed flower petal you receive from Kiawe during Mina’s trial. The goal is to collect seven different kinds of petals.');
INSERT INTO items VALUES (984, 'green-petal', 0, 0, 'unused', 'A pressed flower petal you receive from Mallow during Mina’s trial. The goal is to collect seven different kinds of petals.');
INSERT INTO items VALUES (985, 'yellow-petal', 0, 0, 'unused', 'A pressed flower petal you receive from Sophocles during Mina’s trial. The goal is to collect seven different kinds of petals.');
INSERT INTO items VALUES (986, 'purple-petal', 0, 0, 'unused', 'A pressed flower petal you receive from Nanu during Mina’s trial. The goal is to collect seven different kinds of petals.');
INSERT INTO items VALUES (987, 'rainbow-flower', 0, 0, 'unused', 'A flower made of the petals you received from captains. It’s proof that your growth has been recognized by them.');
INSERT INTO items VALUES (988, 'surge-badge', 0, 0, 'unused', 'A novelty badge that you can receive at the Kantonian Gym. Rumor has it that it imitates the Badge of a Gym somewhere.');
INSERT INTO items VALUES (989, 'n-solarizer--merge', 0, 0, 'unused', 'A machine to fuse Necrozma, which needs light, and Solgaleo.');
INSERT INTO items VALUES (990, 'n-lunarizer--merge', 0, 0, 'unused', 'A machine to fuse Necrozma, which needs light, and Lunala.');
INSERT INTO items VALUES (991, 'n-solarizer--split', 0, 0, 'unused', 'A machine to separate Necrozma, which needed light, from Solgaleo.');
INSERT INTO items VALUES (992, 'n-lunarizer--split', 0, 0, 'unused', 'A machine to separate Necrozma, which needed light, from Lunala.');
INSERT INTO items VALUES (993, 'ilimas-normalium-z', 0, 0, 'unused', 'The Normalium Z you were entrusted with by Ilima. You were asked to place it on the pedestal at the back of Verdant Cavern.');
INSERT INTO items VALUES (994, 'left-poke-ball', 0, 0, 'unused', 'A Poké Ball with a Pokémon that lost its Trainer inside. It seems to be from Ula’ula Island.');
INSERT INTO items VALUES (995, 'roto-hatch', 0, 0, 'unused', 'One of the Rotom Powers. It helps Eggs hatch faster.');
INSERT INTO items VALUES (996, 'roto-bargain', 0, 0, 'unused', 'One of the Rotom Powers. It reduces the prices of products at Poké Marts by half.');
INSERT INTO items VALUES (997, 'roto-prize-money', 0, 0, 'unused', 'One of the Rotom Powers. It triples the prize money you receive after battle.');
INSERT INTO items VALUES (998, 'roto-exp-points', 0, 0, 'unused', 'One of the Rotom Powers. It increases the Exp. Points your Pokémon receive after battle a little.');
INSERT INTO items VALUES (999, 'roto-friendship', 0, 0, 'unused', 'One of the Rotom Powers. It helps Pokémon in your party grow friendly faster.');
INSERT INTO items VALUES (1000, 'roto-encounter', 0, 0, 'unused', 'One of the Rotom Powers. It increases the chance of encountering high-level wild Pokémon a lot for a certain period of time.');
INSERT INTO items VALUES (1001, 'roto-stealth', 0, 0, 'unused', 'One of the Rotom Powers. It prevents you from encountering wild Pokémon for a certain period of time.');
INSERT INTO items VALUES (1002, 'roto-hp-restore', 0, 0, 'unused', 'One of the Rotom Powers. It fully restores the HP of your battling Pokémon.');
INSERT INTO items VALUES (1003, 'roto-pp-restore', 0, 0, 'unused', 'One of the Rotom Powers. It fully restores the PP of your battling Pokémon.');
INSERT INTO items VALUES (1004, 'roto-boost', 0, 0, 'unused', 'One of the Rotom Powers. It raises all stats of your battling Pokémon.');
INSERT INTO items VALUES (1005, 'roto-catch', 0, 0, 'unused', 'One of the Rotom Powers. It increases the chance to catch Pokémon a lot.');
INSERT INTO items VALUES (1006, 'autograph', 0, 0, 'unused', 'The autograph you got from the Vermilion City Gym Leader, Lt. Surge. He wrote, “Good luck!”');
INSERT INTO items VALUES (1007, 'pokemon-box', 0, 0, 'unused', '- - -');
INSERT INTO items VALUES (1008, 'medicine-pocket', 0, 0, 'unused', '- - -');
INSERT INTO items VALUES (1009, 'candy-jar', 0, 0, 'unused', '- - -');
INSERT INTO items VALUES (1010, 'power-up-pocket', 0, 0, 'unused', '- - -');
INSERT INTO items VALUES (1011, 'clothing-trunk', 0, 0, 'unused', 'A very light trunk that can carry clothing for you and your Pokémon.');
INSERT INTO items VALUES (1012, 'catching-pocket', 0, 0, 'unused', '- - -');
INSERT INTO items VALUES (1013, 'battle-pocket', 0, 0, 'unused', '- - -');
INSERT INTO items VALUES (1014, 'silver-razz-berry', 1000, 10, 'catching-bonus', 'A Berry that makes it easier to catch Pokémon when given to them.');
INSERT INTO items VALUES (1015, 'golden-razz-berry', 5000, 10, 'catching-bonus', 'A Berry that makes it drastically easier to catch Pokémon when given to them.');
INSERT INTO items VALUES (1016, 'silver-nanab-berry', 1000, 10, 'catching-bonus', 'A Berry that calms wild Pokémon you’re trying to catch when given to them.');
INSERT INTO items VALUES (1017, 'golden-nanab-berry', 5000, 10, 'catching-bonus', 'A Berry that calms wild Pokémon you’re trying to catch drastically when given to them.');
INSERT INTO items VALUES (1018, 'silver-pinap-berry', 1000, 10, 'catching-bonus', 'A Berry that makes you more likely to get an item when given to Pokémon you’re trying to catch.');
INSERT INTO items VALUES (1019, 'golden-pinap-berry', 5000, 10, 'catching-bonus', 'A Berry that makes you drastically more likely to get an item when given to Pokémon you’re trying to catch.');
INSERT INTO items VALUES (1020, 'secret-key--letsgo', 0, 0, 'plot-advancement', 'The key that unlocks the front door of the Pokémon Gym on Cinnabar Island. It has a red decoration.');
INSERT INTO items VALUES (1021, 'ss-ticket--letsgo', 0, 0, 'plot-advancement', 'The ticket required to board the S.S. Anne. It has a drawing of a ship on it.');
INSERT INTO items VALUES (1022, 'parcel--letsgo', 0, 0, 'plot-advancement', 'A parcel to be delivered to Professor Oak from Viridian City’s Poké Mart.');
INSERT INTO items VALUES (1023, 'card-key--letsgo', 0, 0, 'plot-advancement', 'A card key that unlocks doors in Silph Co.’s head office in Saffron City.');
INSERT INTO items VALUES (1024, 'stretchy-spring', 20, 30, 'loot', 'A thin small spring. It’s totally stretched out, and what it’s used for is unknown.');
INSERT INTO items VALUES (1025, 'chalky-stone', 60, 30, 'loot', 'A small whitish stone picked up at the edge of the road.');
INSERT INTO items VALUES (1026, 'marble', 300, 30, 'loot', 'A round glass marble. You can see colored glass inside the transparent marble.');
INSERT INTO items VALUES (1027, 'lone-earring', 600, 30, 'loot', 'A single earring that somebody dropped.');
INSERT INTO items VALUES (1028, 'beach-glass', 800, 30, 'loot', 'A piece of colored glass. Waves have rounded its edges. It’s slightly rough to the touch.');
INSERT INTO items VALUES (1029, 'gold-leaf', 1000, 30, 'loot', 'A mysterious gold leaf. No trees with this leaf have been found yet.');
INSERT INTO items VALUES (1030, 'silver-leaf', 1000, 30, 'loot', 'A mysterious silver leaf. No trees with this leaf have been found yet.');
INSERT INTO items VALUES (1031, 'polished-mud-ball', 1200, 30, 'loot', 'A ball made of mud. It had been polished for such a long time that the surface is very shiny.');
INSERT INTO items VALUES (1032, 'tropical-shell', 2000, 30, 'loot', 'A beautiful white shell that may have drifted from a sea in a warm region.');
INSERT INTO items VALUES (1033, 'leaf-letter--pikachu', 0, 30, 'loot', 'A letter written on a leaf. Something is written using Pikachu’s footprints.');
INSERT INTO items VALUES (1034, 'leaf-letter--eevee', 0, 30, 'loot', 'A letter written on a leaf. Something is written using Eevee’s footprints.');
INSERT INTO items VALUES (1035, 'small-bouquet', 0, 30, 'loot', 'A small bouquet that was made with heart and soul for a single Trainer.');
INSERT INTO items VALUES (1036, 'lure', 400, 30, 'spelunking', 'A glass bottle of perfume that makes rare Pokémon more likely to appear.');
INSERT INTO items VALUES (1037, 'super-lure', 700, 30, 'spelunking', 'A glass bottle of perfume that makes rare Pokémon more likely to appear. It lasts longer than a Lure.');
INSERT INTO items VALUES (1038, 'max-lure', 900, 30, 'spelunking', 'A glass bottle of perfume that makes rare Pokémon more likely to appear. It lasts longer than a Super Lure.');
INSERT INTO items VALUES (1039, 'pewter-crunchies', 250, 30, 'status-cures', 'Pewter City’s famous crunchy snack. They can be used to heal all status conditions of a single Pokémon.');
