INSERT INTO items VALUES (1138, 'endorsement', 0, 0, 'plot-advancement', 'A letter of recommendation that you’ll need in order to participate in the Gym Challenge.');
INSERT INTO items VALUES (1139, 'pokemon-box-link', 0, 0, 'gameplay', 'A device that allows you to access the Pokémon storage system. There are some places where it won’t work.');
INSERT INTO items VALUES (1140, 'wishing-star', 0, 0, 'plot-advancement', 'A stone found in the Galar region with a mysterious power. It’s said that your dreams come true if you find one.');
INSERT INTO items VALUES (1141, 'dynamax-band', 0, 0, 'plot-advancement', 'A Wishing Star has been affixed to it. It lets out a light that allows Pokémon to Dynamax when at a Power Spot.');
INSERT INTO items VALUES (1142, 'fishing-rod--galar', 0, 0, 'gameplay', 'Use it by the water to fish up various kinds of Pokémon.');
INSERT INTO items VALUES (1143, 'rotom-bike', 0, 0, 'gameplay', 'This bike can be combined with the Pokémon Rotom to use a turbo boost.');
INSERT INTO items VALUES (1144, 'sausages', 400, 10, 'curry-ingredients', 'One of the many ingredients that can be used for cooking at your camp. These sausages should be boiled before eating.');
INSERT INTO items VALUES (1145, 'bobs-food-tin', 950, 80, 'curry-ingredients', 'One of the many ingredients that can be used for cooking at your camp. The tinned food that Bob sells is curiously popular in Galar.');
INSERT INTO items VALUES (1146, 'bachs-food-tin', 950, 80, 'curry-ingredients', 'One of the many ingredients that can be used for cooking at your camp. The tinned food that Bach sells is curiously popular in Galar.');
INSERT INTO items VALUES (1147, 'tin-of-beans', 400, 80, 'curry-ingredients', 'One of the many ingredients that can be used for cooking at your camp. When simmered, the beans suffuse a dish with their mild flavor.');
INSERT INTO items VALUES (1148, 'bread', 150, 10, 'curry-ingredients', 'One of the many ingredients that can be used for cooking at your camp. An indispensable tool for mopping up that extra curry left on your plate.');
INSERT INTO items VALUES (1149, 'pasta', 150, 10, 'curry-ingredients', 'One of the many ingredients that can be used for cooking at your camp. These flour noodles make for a surprisingly good match with curry.');
INSERT INTO items VALUES (1150, 'mixed-mushrooms', 400, 10, 'curry-ingredients', 'One of the many ingredients that can be used for cooking at your camp. The chewy texture of the mushrooms transforms any dish they’re added to.');
INSERT INTO items VALUES (1151, 'smoke-poke-tail', 2200, 10, 'curry-ingredients', 'One of the many ingredients that can be used for cooking at your camp. When a Slowpoke’s tail falls off, it grows back quickly.');
INSERT INTO items VALUES (1152, 'large-leek', 2200, 20, 'curry-ingredients', 'One of the many ingredients that can be used for cooking at your camp. Whether this is the kind of vegetable stalk that Farfetch’d like is unknown.');
INSERT INTO items VALUES (1153, 'fancy-apple', 2200, 20, 'curry-ingredients', 'One of the many ingredients that can be used for cooking at your camp. An apple chosen above others. It has spectacular form and a brilliant sheen.');
INSERT INTO items VALUES (1154, 'brittle-bones', 950, 30, 'curry-ingredients', 'One of the many ingredients that can be used for cooking at your camp. The taste boiled off from the bones is sure to give a dish a light umami taste.');
INSERT INTO items VALUES (1155, 'pack-of-potatoes', 400, 10, 'curry-ingredients', 'One of the many ingredients that can be used for cooking at your camp. Potatoes help mellow out a spicy taste, to make a dish more mild.');
INSERT INTO items VALUES (1156, 'pungent-root', 950, 10, 'curry-ingredients', 'One of the many ingredients that can be used for cooking at your camp. Though carelessly picked, these herbs can add a fragrant accent to a dish.');
INSERT INTO items VALUES (1157, 'salad-mix', 400, 10, 'curry-ingredients', 'One of the many ingredients that can be used for cooking at your camp. The assortment of vegetables looks quite appealing and healthy.');
INSERT INTO items VALUES (1158, 'fried-food', 150, 10, 'curry-ingredients', 'One of the many ingredients that can be used for cooking at your camp. It’s been a while since it was fried, so it’s gotten greasy.');
INSERT INTO items VALUES (1159, 'boiled-egg', 2200, 20, 'curry-ingredients', 'One of the many ingredients that can be used for cooking at your camp. Even just one boiled egg can really enhance a dish.');
INSERT INTO items VALUES (1160, 'camping-gear', 0, 0, 'gameplay', 'Everything you need to set up a tent and get cooking in a Wild Area or at a camping spot.');
INSERT INTO items VALUES (1161, 'rusted-sword', 0, 0, 'species-specific', 'It is said that a hero used this sword to halt a terrible disaster in ancient times. But it’s grown rusty and worn.');
INSERT INTO items VALUES (1162, 'rusted-shield', 0, 0, 'species-specific', 'It is said that a hero used this shield to halt a terrible disaster in ancient times. But it’s grown rusty and worn.');
INSERT INTO items VALUES (1163, 'fossilized-bird', 5000, 100, 'dex-completion', 'The fossil of an ancient Pokémon that once soared through the sky. What it looked like is a mystery.');
INSERT INTO items VALUES (1164, 'fossilized-fish', 5000, 100, 'dex-completion', 'The fossil of an ancient Pokémon that once lived in the sea. What it looked like is a mystery.');
INSERT INTO items VALUES (1165, 'fossilized-drake', 5000, 100, 'dex-completion', 'The fossil of an ancient Pokémon that once roamed the land. What it looked like is a mystery.');
INSERT INTO items VALUES (1166, 'fossilized-dino', 5000, 100, 'dex-completion', 'The fossil of an ancient Pokémon that once lived in the sea. What it looked like is a mystery.');
INSERT INTO items VALUES (1167, 'strawberry-sweet', 500, 10, 'evolution', 'A strawberry-shaped sweet. When a Milcery holds this, it will spin around happily.');
INSERT INTO items VALUES (1168, 'love-sweet', 500, 10, 'evolution', 'A heart-shaped sweet. When a Milcery holds this, it spins around happily.');
INSERT INTO items VALUES (1169, 'berry-sweet', 500, 10, 'evolution', 'A berry-shaped sweet. When a Milcery holds this, it spins around happily.');
INSERT INTO items VALUES (1170, 'clover-sweet', 500, 10, 'evolution', 'A clover-shaped sweet. When a Milcery holds this, it spins around happily.');
INSERT INTO items VALUES (1171, 'flower-sweet', 500, 10, 'evolution', 'A flower-shaped sweet. When a Milcery holds this, it spins around happily.');
INSERT INTO items VALUES (1172, 'star-sweet', 500, 10, 'evolution', 'A star-shaped sweet. When a Milcery holds this, it spins around happily.');
INSERT INTO items VALUES (1173, 'ribbon-sweet', 500, 10, 'evolution', 'A ribbon-shaped sweet. When a Milcery holds this, it spins around happily.');
INSERT INTO items VALUES (1174, 'sweet-apple', 2200, 30, 'evolution', 'A peculiar apple that can make a certain species of Pokémon evolve. It’s exceptionally sweet.');
INSERT INTO items VALUES (1175, 'tart-apple', 2200, 30, 'evolution', 'A peculiar apple that can make a certain species of Pokémon evolve. It’s exceptionally tart.');
INSERT INTO items VALUES (1176, 'throat-spray', 4000, 30, 'held-items', 'Raises Sp. Atk when a Pokémon uses a sound-based move.');
INSERT INTO items VALUES (1177, 'eject-pack', 4000, 50, 'held-items', 'An item to be held by a Pokémon. When the holder’s stats are lowered, it will be switched out of battle.');
INSERT INTO items VALUES (1178, 'heavy-duty-boots', 4000, 80, 'held-items', 'These boots prevent the effects of traps set on the battlefield.');
INSERT INTO items VALUES (1179, 'blunder-policy', 4000, 80, 'held-items', 'Raises Speed sharply when a Pokémon misses with a move because of accuracy.');
INSERT INTO items VALUES (1180, 'room-service', 4000, 100, 'held-items', 'An item to be held by a Pokémon. Lowers Speed when Trick Room takes effect.');
INSERT INTO items VALUES (1181, 'utility-umbrella', 4000, 60, 'held-items', 'An item to be held by a Pokémon. This sturdy umbrella protects the holder from the effects of rain and harsh sunlight.');
INSERT INTO items VALUES (1182, 'exp-candy-xs', 20, 30, 'vitamins', 'A candy that is packed with energy. When consumed, it will grant a single Pokémon a very small amount of Exp. Points.');
INSERT INTO items VALUES (1183, 'exp-candy-s', 240, 30, 'vitamins', 'A candy that is packed with energy. When consumed, it will grant a single Pokémon a small amount of Exp. Points.');
INSERT INTO items VALUES (1184, 'exp-candy-m', 1000, 30, 'vitamins', 'A candy that is packed with energy. When consumed, it will grant a single Pokémon a moderate amount of Exp. Points.');
INSERT INTO items VALUES (1185, 'exp-candy-l', 3000, 30, 'vitamins', 'A candy that is packed with energy. When consumed, it will grant a single Pokémon a large amount of Exp. Points.');
INSERT INTO items VALUES (1186, 'exp-candy-xl', 10000, 30, 'vitamins', 'A candy that is packed with energy. When consumed, it will grant a single Pokémon a very large amount of Exp. Points.');
INSERT INTO items VALUES (1187, 'dynamax-candy', 0, 30, 'vitamins', 'A candy that is packed with energy. When consumed, it will raise the Dynamax Level of a single Pokémon by one. A higher level means higher HP when Dynamaxed.');
INSERT INTO items VALUES (1188, 'tr00', 4000, 10, 'all-machines', 'A frenetic dance to uplift the fighting spirit. This sharply raises the user’s Attack stat.');
INSERT INTO items VALUES (1189, 'tr01', 6000, 85, 'all-machines', 'The user drops onto the target with its full body weight. This may also leave the target with paralysis.');
INSERT INTO items VALUES (1190, 'tr02', 10000, 90, 'all-machines', 'The target is scorched with an intense blast of fire. This may also leave the target with a burn.');
INSERT INTO items VALUES (1191, 'tr03', 16000, 110, 'all-machines', 'The target is blasted by a huge volume of water launched under great pressure.');
INSERT INTO items VALUES (1192, 'tr04', 10000, 90, 'all-machines', 'The user attacks everything around it by swamping its surroundings with a giant wave.');
INSERT INTO items VALUES (1193, 'tr05', 10000, 90, 'all-machines', 'The target is struck with an icy-cold beam of energy. This may also leave the target frozen.');
INSERT INTO items VALUES (1194, 'tr06', 16000, 110, 'all-machines', 'A howling blizzard is summoned to strike opposing Pokémon. This may also leave the opposing Pokémon frozen.');
INSERT INTO items VALUES (1195, 'tr07', 6000, 10, 'all-machines', 'A powerful low kick that makes the target fall over. The heavier the target, the greater the move’s power.');
INSERT INTO items VALUES (1196, 'tr08', 10000, 90, 'all-machines', 'A strong electric blast crashes down on the target. This may also leave the target with paralysis.');
INSERT INTO items VALUES (1197, 'tr09', 16000, 110, 'all-machines', 'A wicked thunderbolt is dropped on the target to inflict damage. This may also leave the target with paralysis.');
INSERT INTO items VALUES (1198, 'tr10', 16000, 100, 'all-machines', 'The user sets off an earthquake that strikes every Pokémon around it.');
INSERT INTO items VALUES (1199, 'tr11', 10000, 90, 'all-machines', 'The target is hit by a strong telekinetic force. This may also lower the target’s Sp. Def stat.');
INSERT INTO items VALUES (1200, 'tr12', 4000, 10, 'all-machines', 'The user relaxes and lightens its body to move faster. This sharply raises the Speed stat.');
INSERT INTO items VALUES (1201, 'tr13', 2000, 10, 'all-machines', 'The user takes a deep breath and focuses so that critical hits land more easily.');
INSERT INTO items VALUES (1202, 'tr14', 2000, 10, 'all-machines', 'The user waggles a finger and stimulates its brain into randomly using nearly any move.');
INSERT INTO items VALUES (1203, 'tr15', 16000, 110, 'all-machines', 'The target is attacked with an intense blast of all-consuming fire. This may also leave the target with a burn.');
INSERT INTO items VALUES (1204, 'tr16', 6000, 80, 'all-machines', 'The user charges at the target and may make it flinch.');
INSERT INTO items VALUES (1205, 'tr17', 4000, 10, 'all-machines', 'The user temporarily empties its mind to forget its concerns. This sharply raises the user’s Sp. Def stat.');
INSERT INTO items VALUES (1206, 'tr18', 6000, 80, 'all-machines', 'The user drains the target’s blood. The user’s HP is restored by half the damage taken by the target.');
INSERT INTO items VALUES (1207, 'tr19', 4000, 80, 'all-machines', 'The user strikes with a simultaneous three-beam attack. This may also burn, freeze, or paralyze the target.');
INSERT INTO items VALUES (1208, 'tr20', 6000, 10, 'all-machines', 'The user creates a substitute for itself using some of its HP. The substitute serves as the user’s decoy.');
INSERT INTO items VALUES (1209, 'tr21', 4000, 10, 'all-machines', 'An all-out attack that becomes more powerful the less HP the user has.');
INSERT INTO items VALUES (1210, 'tr22', 10000, 90, 'all-machines', 'Unsanitary sludge is hurled at the target. This may also poison the target.');
INSERT INTO items VALUES (1211, 'tr23', 4000, 10, 'all-machines', 'The user lays a trap of spikes at the opposing team’s feet. The trap hurts Pokémon that switch into battle.');
INSERT INTO items VALUES (1212, 'tr24', 16000, 120, 'all-machines', 'The user rampages and attacks for two to three turns. The user then becomes confused.');
INSERT INTO items VALUES (1213, 'tr25', 6000, 80, 'all-machines', 'The user materializes an odd psychic wave to attack the target. This attack does physical damage.');
INSERT INTO items VALUES (1214, 'tr26', 2000, 10, 'all-machines', 'The user endures any attack with at least 1 HP. Its chance of failing rises if it is used in succession.');
INSERT INTO items VALUES (1215, 'tr27', 4000, 10, 'all-machines', 'While it is asleep, the user randomly uses one of the moves it knows.');
INSERT INTO items VALUES (1216, 'tr28', 16000, 120, 'all-machines', 'Using its tough and impressive horn, the user rams into the target with no letup.');
INSERT INTO items VALUES (1217, 'tr29', 4000, 10, 'all-machines', 'The user switches places with a party Pokémon in waiting and passes along any stat changes.');
INSERT INTO items VALUES (1218, 'tr30', 4000, 10, 'all-machines', 'The user compels the target to keep using the move it encored for three turns.');
INSERT INTO items VALUES (1219, 'tr31', 10000, 100, 'all-machines', 'The target is slammed with a steel-hard tail. This may also lower the target’s Defense stat.');
INSERT INTO items VALUES (1220, 'tr32', 6000, 80, 'all-machines', 'The user crunches up the target with sharp fangs. This may also lower the target’s Defense stat.');
INSERT INTO items VALUES (1221, 'tr33', 6000, 80, 'all-machines', 'The user hurls a shadowy blob at the target. This may also lower the target’s Sp. Def stat.');
INSERT INTO items VALUES (1222, 'tr34', 6000, 120, 'all-machines', 'Two turns after this move is used, a hunk of psychic energy attacks the target.');
INSERT INTO items VALUES (1223, 'tr35', 6000, 90, 'all-machines', 'The user attacks in an uproar for three turns. During that time, no Pokémon can fall asleep.');
INSERT INTO items VALUES (1224, 'tr36', 10000, 95, 'all-machines', 'The user attacks by exhaling hot breath on opposing Pokémon. This may also leave those Pokémon with a burn.');
INSERT INTO items VALUES (1225, 'tr37', 4000, 10, 'all-machines', 'The target is taunted into a rage that allows it to use only attack moves for three turns.');
INSERT INTO items VALUES (1226, 'tr38', 4000, 10, 'all-machines', 'The user catches the target off guard and swaps its held item with its own.');
INSERT INTO items VALUES (1227, 'tr39', 16000, 120, 'all-machines', 'The user attacks the target with great power. However, this also lowers the user’s Attack and Defense stats.');
INSERT INTO items VALUES (1228, 'tr40', 2000, 10, 'all-machines', 'The user employs its psychic power to exchange Abilities with the target.');
INSERT INTO items VALUES (1229, 'tr41', 6000, 85, 'all-machines', 'The user launches a kick that lands a critical hit more easily. This may also leave the target with a burn.');
INSERT INTO items VALUES (1230, 'tr42', 10000, 90, 'all-machines', 'The user lets loose a horribly echoing shout with the power to inflict damage.');
INSERT INTO items VALUES (1231, 'tr43', 16000, 130, 'all-machines', 'The user attacks the target at full power. The attack’s recoil harshly lowers the user’s Sp. Atk stat.');
INSERT INTO items VALUES (1232, 'tr44', 4000, 10, 'all-machines', 'The user absorbs a mystical power from space to raise its Defense and Sp. Def stats.');
INSERT INTO items VALUES (1233, 'tr45', 10000, 90, 'all-machines', 'The user attacks by shooting muddy water at opposing Pokémon. This may also lower their accuracy.');
INSERT INTO items VALUES (1234, 'tr46', 4000, 10, 'all-machines', 'The user hardens its body’s surface like iron, sharply raising its Defense stat.');
INSERT INTO items VALUES (1235, 'tr47', 6000, 80, 'all-machines', 'The user slashes the target with huge sharp claws.');
INSERT INTO items VALUES (1236, 'tr48', 4000, 10, 'all-machines', 'The user tenses its muscles to bulk up its body, raising both its Attack and Defense stats.');
INSERT INTO items VALUES (1237, 'tr49', 4000, 10, 'all-machines', 'The user quietly focuses its mind and calms its spirit to raise its Sp. Atk and Sp. Def stats.');
INSERT INTO items VALUES (1238, 'tr50', 10000, 90, 'all-machines', 'The user handles a sharp leaf like a sword and attacks by cutting its target. Critical hits land more easily.');
INSERT INTO items VALUES (1239, 'tr51', 4000, 10, 'all-machines', 'The user vigorously performs a mystic, powerful dance that raises its Attack and Speed stats.');
INSERT INTO items VALUES (1240, 'tr52', 6000, 10, 'all-machines', 'The user tackles the target with a high-speed spin. The slower the user compared to the target, the greater the move’s power.');
INSERT INTO items VALUES (1241, 'tr53', 16000, 120, 'all-machines', 'The user fights the target up close without guarding itself. This also lowers the user’s Defense and Sp. Def stats.');
INSERT INTO items VALUES (1242, 'tr54', 4000, 10, 'all-machines', 'The user lays a trap of poison spikes at the feet of the opposing team. The spikes will poison opposing Pokémon that switch into battle.');
INSERT INTO items VALUES (1243, 'tr55', 16000, 120, 'all-machines', 'The user cloaks itself in fire and charges the target. This also damages the user quite a lot. This attack may leave the target with a burn.');
INSERT INTO items VALUES (1244, 'tr56', 6000, 80, 'all-machines', 'The user lets loose a blast of aura power from deep within its body at the target. This attack never misses.');
INSERT INTO items VALUES (1245, 'tr57', 6000, 80, 'all-machines', 'The target is stabbed with a tentacle, arm, or the like steeped in poison. This may also poison the target.');
INSERT INTO items VALUES (1246, 'tr58', 6000, 80, 'all-machines', 'The user releases a horrible aura imbued with dark thoughts. This may also make the target flinch.');
INSERT INTO items VALUES (1247, 'tr59', 6000, 80, 'all-machines', 'The user slams a barrage of hard-shelled seeds down on the target from above.');
INSERT INTO items VALUES (1248, 'tr60', 6000, 80, 'all-machines', 'The user slashes at the target by crossing its scythes or claws as if they were a pair of scissors.');
INSERT INTO items VALUES (1249, 'tr61', 10000, 90, 'all-machines', 'The user generates a damaging sound wave by vibration. This may also lower the target’s Sp. Def stat.');
INSERT INTO items VALUES (1250, 'tr62', 6000, 85, 'all-machines', 'The target is attacked with a shock wave generated by the user’s gaping mouth.');
INSERT INTO items VALUES (1251, 'tr63', 6000, 80, 'all-machines', 'The user attacks with a ray of light that sparkles as if it were made of gemstones.');
INSERT INTO items VALUES (1252, 'tr64', 16000, 120, 'all-machines', 'The user heightens its mental focus and unleashes its power. This may also lower the target’s Sp. Def stat.');
INSERT INTO items VALUES (1253, 'tr65', 10000, 90, 'all-machines', 'The user draws power from nature and fires it at the target. This may also lower the target’s Sp. Def stat.');
INSERT INTO items VALUES (1254, 'tr66', 16000, 120, 'all-machines', 'The user tucks in its wings and charges from a low altitude. This also damages the user quite a lot.');
INSERT INTO items VALUES (1255, 'tr67', 10000, 90, 'all-machines', 'The user makes the ground under the target erupt with power. This may also lower the target’s Sp. Def stat.');
INSERT INTO items VALUES (1256, 'tr68', 4000, 10, 'all-machines', 'The user stimulates its brain by thinking bad thoughts. This sharply raises the user’s Sp. Atk stat.');
INSERT INTO items VALUES (1257, 'tr69', 6000, 80, 'all-machines', 'The user focuses its willpower to its head and attacks the target. This may also make the target flinch.');
INSERT INTO items VALUES (1258, 'tr70', 10000, 80, 'all-machines', 'The user gathers all its light energy and releases it all at once. This may also lower the target’s Sp. Def stat.');
INSERT INTO items VALUES (1259, 'tr71', 16000, 130, 'all-machines', 'The user whips up a storm of leaves around the target. The attack’s recoil harshly lowers the user’s Sp. Atk stat.');
INSERT INTO items VALUES (1260, 'tr72', 16000, 120, 'all-machines', 'The user violently whirls its vines, tentacles, or the like to harshly lash the target.');
INSERT INTO items VALUES (1261, 'tr73', 16000, 120, 'all-machines', 'The user shoots filthy garbage at the target to attack. This may also poison the target.');
INSERT INTO items VALUES (1262, 'tr74', 10000, 80, 'all-machines', 'The user slams the target with its steel-hard head. This may also make the target flinch.');
INSERT INTO items VALUES (1263, 'tr75', 16000, 100, 'all-machines', 'The user stabs the target from below with sharpened stones. Critical hits land more easily.');
INSERT INTO items VALUES (1264, 'tr76', 6000, 10, 'all-machines', 'The user lays a trap of levitating stones around the opposing team. The trap hurts opposing Pokémon that switch into battle.');
INSERT INTO items VALUES (1265, 'tr77', 6000, 10, 'all-machines', 'The user snares the target with grass and trips it. The heavier the target, the greater the move’s power.');
INSERT INTO items VALUES (1266, 'tr78', 10000, 95, 'all-machines', 'The user strikes everything around it by swamping the area with a giant sludge wave. This may also poison those hit.');
INSERT INTO items VALUES (1267, 'tr79', 6000, 10, 'all-machines', 'The user slams into the target with its heavy body. The more the user outweighs the target, the greater the move’s power.');
INSERT INTO items VALUES (1268, 'tr80', 6000, 10, 'all-machines', 'The user hurls an electric orb at the target. The faster the user is than the target, the greater the move’s power.');
INSERT INTO items VALUES (1269, 'tr81', 6000, 95, 'all-machines', 'The user turns the target’s power against it. The higher the target’s Attack stat, the greater the damage it deals.');
INSERT INTO items VALUES (1270, 'tr82', 4000, 20, 'all-machines', 'The user attacks the target with stored power. The more the user’s stats are raised, the greater the move’s power.');
INSERT INTO items VALUES (1271, 'tr83', 4000, 10, 'all-machines', 'The user teleports using a strange power and switches places with one of its allies.');
INSERT INTO items VALUES (1272, 'tr84', 6000, 80, 'all-machines', 'The user shoots boiling hot water at its target. This may also leave the target with a burn.');
INSERT INTO items VALUES (1273, 'tr85', 2000, 10, 'all-machines', 'The user is roused, and its Attack and Sp. Atk stats increase.');
INSERT INTO items VALUES (1274, 'tr86', 10000, 90, 'all-machines', 'The user shrouds itself in electricity and smashes into its target. This also damages the user a little.');
INSERT INTO items VALUES (1275, 'tr87', 6000, 80, 'all-machines', 'The user crashes into its target while rotating its body like a drill. Critical hits land more easily.');
INSERT INTO items VALUES (1276, 'tr88', 6000, 10, 'all-machines', 'The user slams its target with its flame-covered body. The more the user outweighs the target, the greater the move’s power.');
INSERT INTO items VALUES (1277, 'tr89', 16000, 110, 'all-machines', 'The user attacks by wrapping its opponent in a fierce wind that flies up into the sky. This may also confuse the target.');
INSERT INTO items VALUES (1278, 'tr90', 10000, 90, 'all-machines', 'The user plays rough with the target and attacks it. This may also lower the target’s Attack stat.');
INSERT INTO items VALUES (1279, 'tr91', 4000, 10, 'all-machines', 'Opposing Pokémon are drenched in an odd poisonous liquid. This lowers the Attack, Sp. Atk, and Speed stats of a poisoned target.');
INSERT INTO items VALUES (1280, 'tr92', 6000, 80, 'all-machines', 'The user damages opposing Pokémon by emitting a powerful flash.');
INSERT INTO items VALUES (1281, 'tr93', 10000, 85, 'all-machines', 'The user swings both arms and hits the target. The target’s stat changes don’t affect this attack’s damage.');
INSERT INTO items VALUES (1282, 'tr94', 10000, 95, 'all-machines', 'The user fiercely attacks the target using its entire body.');
INSERT INTO items VALUES (1283, 'tr95', 6000, 80, 'all-machines', 'The user attacks the target’s throat, and the resultant suffering prevents the target from using moves that emit sound for two turns.');
INSERT INTO items VALUES (1284, 'tr96', 10000, 90, 'all-machines', 'The user attacks the enemy with a pollen puff that explodes. If the target is an ally, it gives the ally a pollen puff that restores its HP instead.');
INSERT INTO items VALUES (1285, 'tr97', 10000, 85, 'all-machines', 'The user bites the target with its psychic capabilities. This can also destroy Light Screen and Reflect.');
INSERT INTO items VALUES (1286, 'tr98', 6000, 85, 'all-machines', 'The user slams into the target using a full-force blast of water. This may also lower the target’s Defense stat.');
INSERT INTO items VALUES (1287, 'tr99', 6000, 80, 'all-machines', 'The user attacks by slamming its body into the target. The higher the user’s Defense, the more damage it can inflict on the target.');
INSERT INTO items VALUES (1288, 'tm00', 10000, 0, 'all-machines', 'The target is slugged by a punch thrown with muscle-packed power.');
INSERT INTO items VALUES (1289, 'lonely-mint', 20, 10, 'nature-mints', 'When a Pokémon smells this mint, its Attack will grow more easily, but its Defense will grow more slowly.');
INSERT INTO items VALUES (1290, 'adamant-mint', 20, 10, 'nature-mints', 'When a Pokémon smells this mint, its Attack will grow more easily, but its Sp. Atk will grow more slowly.');
