INSERT INTO items VALUES (1298, 'mild-mint', 20, 10, 'nature-mints', 'When a Pokémon smells this mint, its Sp. Atk will grow more easily, but its Defense will grow more slowly.');
INSERT INTO items VALUES (1299, 'rash-mint', 20, 10, 'nature-mints', 'When a Pokémon smells this mint, its Sp. Atk will grow more easily, but its Sp. Def will grow more slowly.');
INSERT INTO items VALUES (1300, 'quiet-mint', 20, 10, 'nature-mints', 'When a Pokémon smells this mint, its Sp. Atk will grow more easily, but its Speed will grow more slowly.');
INSERT INTO items VALUES (1301, 'calm-mint', 20, 10, 'nature-mints', 'When a Pokémon smells this mint, its Sp. Def will grow more easily, but its Attack will grow more slowly.');
INSERT INTO items VALUES (1302, 'gentle-mint', 20, 10, 'nature-mints', 'When a Pokémon smells this mint, its Sp. Def will grow more easily, but its Defense will grow more slowly.');
INSERT INTO items VALUES (1303, 'careful-mint', 20, 10, 'nature-mints', 'When a Pokémon smells this mint, its Sp. Def will grow more easily, but its Sp. Atk will grow more slowly.');
INSERT INTO items VALUES (1304, 'sassy-mint', 20, 10, 'nature-mints', 'When a Pokémon smells this mint, its Sp. Def will grow more easily, but its Speed will grow more slowly.');
INSERT INTO items VALUES (1305, 'timid-mint', 20, 10, 'nature-mints', 'When a Pokémon smells this mint, its Speed will grow more easily, but its Attack will grow more slowly.');
INSERT INTO items VALUES (1306, 'hasty-mint', 20, 10, 'nature-mints', 'When a Pokémon smells this mint, its Speed will grow more easily, but its Defense will grow more slowly.');
INSERT INTO items VALUES (1307, 'jolly-mint', 20, 10, 'nature-mints', 'When a Pokémon smells this mint, its Speed will grow more easily, but its Sp. Atk will grow more slowly.');
INSERT INTO items VALUES (1308, 'naive-mint', 20, 10, 'nature-mints', 'When a Pokémon smells this mint, its Speed will grow more easily, but its Sp. Def will grow more slowly.');
INSERT INTO items VALUES (1309, 'serious-mint', 20, 10, 'nature-mints', 'When a Pokémon smells this mint, all of its stats will grow at an equal rate.');
INSERT INTO items VALUES (1310, 'wishing-piece', 20, 50, 'collectibles', 'Throw one into a Pokémon Den to attract a wild Dynamax Pokémon.');
INSERT INTO items VALUES (1311, 'cracked-pot', 1600, 80, 'evolution', 'A peculiar teapot that can make a certain species of Pokémon evolve. It may be cracked, but tea poured from it is delicious.');
INSERT INTO items VALUES (1312, 'chipped-pot', 38000, 80, 'evolution', 'A peculiar teapot that can make a certain species of Pokémon evolve. It may be chipped, but tea poured from it is delicious.');
INSERT INTO items VALUES (1313, 'hi-tech-earbuds', 0, 0, 'gameplay', 'Strange earbuds that allow you to freely control the volume of various sounds.');
INSERT INTO items VALUES (1314, 'fruit-bunch', 2200, 10, 'curry-ingredients', 'One of the many ingredients that can be used for cooking at your camp. The syrupy fruits give off a strong tropical feel.');
INSERT INTO items VALUES (1315, 'moomoo-cheese', 2200, 20, 'curry-ingredients', 'One of the many ingredients that can be used for cooking at your camp. Melted cheese can really give a curry some richness.');
INSERT INTO items VALUES (1316, 'spice-mix', 400, 50, 'curry-ingredients', 'One of the many ingredients that can be used for cooking at your camp. There are over fifty spices contained within this ingredient’s hot flavor.');
INSERT INTO items VALUES (1317, 'fresh-cream', 950, 10, 'curry-ingredients', 'One of the many ingredients that can be used for cooking at your camp. Add some whipped cream to a spicy curry to give it some sweetness.');
INSERT INTO items VALUES (1318, 'packaged-curry', 950, 10, 'curry-ingredients', 'One of the many ingredients that can be used for cooking at your camp. Using packaged curry helps make sure there are no slipups when cooking.');
INSERT INTO items VALUES (1319, 'coconut-milk', 950, 10, 'curry-ingredients', 'One of the many ingredients that can be used for cooking at your camp. The refined sweetness of this coconut milk makes it quite popular.');
INSERT INTO items VALUES (1320, 'instant-noodles', 150, 10, 'curry-ingredients', 'One of the many ingredients that can be used for cooking at your camp. It has a junk-food sort of taste, but it goes well with curry.');
INSERT INTO items VALUES (1321, 'precooked-burger', 150, 10, 'curry-ingredients', 'One of the many ingredients that can be used for cooking at your camp. If you’re unsure about what to cook, you can’t go wrong with some burger.');
INSERT INTO items VALUES (1322, 'gigantamix', 15000, 50, 'curry-ingredients', 'One of the many ingredients that can be used for cooking at your camp. A mysterious spice. Even a tiny sprinkle is sure to make a curry gigantic.');
INSERT INTO items VALUES (1323, 'wishing-chip', 0, 0, 'unused', 'Toss a number of them into a Pokémon Den for the chance to attract a wild Dynamax Pokémon.');
INSERT INTO items VALUES (1324, 'rotom-bike--water-mode', 0, 0, 'unused', 'This bike can be combined with the Pokémon Rotom to not only do a turbo boost but also run on the water.');
INSERT INTO items VALUES (1325, 'catching-charm', 0, 0, 'gameplay', 'Holding it is said to increase the chance of getting a critical catch. Curiously, the charm doesn’t shake much.');
INSERT INTO items VALUES (1326, 'old-letter', 0, 0, 'plot-advancement', 'A letter entrusted to you by a girl, to be delivered to a boy. Strangely, it looks old to you.');
INSERT INTO items VALUES (1327, 'band-autograph', 0, 0, 'unused', 'It’s signed by all members of the Galar region’s most charismatic band, the Maximizers.');
INSERT INTO items VALUES (1328, 'sonias-book', 0, 0, 'plot-advancement', 'Professor Sonia’s published writings. Her new discoveries about the Galar region’s legends are recorded in this enjoyable read.');
INSERT INTO items VALUES (1329, 'rotom-catalog', 0, 0, 'gameplay', 'A catalog of devices that Rotom like. Use the catalog to have Rotom hop in and out of the various devices listed within.');
