INSERT INTO items VALUES (1630, 'max-honey', 4000, 30, 'revival', 'Honey that Dynamax Vespiquen produces. Adding this honey to Max Soup makes the taste very smooth. It also has the same effect as a Max Revive.');
INSERT INTO items VALUES (1631, 'max-mushrooms', 6000, 30, 'stat-boosts', 'Mushrooms that have the power of changing Dynamax forms. They boost all stats of a Pokémon during battle.');
INSERT INTO items VALUES (1632, 'galarica-twig', 20, 30, 'collectibles', 'A twig from a species of tree called Galarica that grows in certain areas around the Galar region. It’s a material for an accessory for a certain Pokémon.');
INSERT INTO items VALUES (1633, 'galarica-cuff', 3000, 30, 'collectibles', 'A cuff made from woven-together Galarica Twigs. Giving it to Galarian Slowpoke makes the Pokémon very happy.');
INSERT INTO items VALUES (1634, 'style-card', 0, 0, 'gameplay', 'A card that increases the selection in boutiques and hair salons.');
INSERT INTO items VALUES (1635, 'armor-pass', 0, 0, 'plot-advancement', 'A pass to go to the Isle of Armor. Show it to the rail staff at Wedgehurst Station.');
INSERT INTO items VALUES (1636, 'rotom-bike--sparkling-white', 0, 0, 'unused', 'This bike can do a turbo boost and run on the water using Rotom’s power. It’s a sparkling white that shines brilliantly.');
INSERT INTO items VALUES (1637, 'rotom-bike--glistening-black', 0, 0, 'unused', 'This bike can do a turbo boost and run on the water using Rotom’s power. It’s a glistening black that shines reddish-black.');
INSERT INTO items VALUES (1638, 'exp-charm', 0, 0, 'gameplay', 'A charm that increases the Exp. Points that Pokémon can get. A machine-like object is inside the charm.');
INSERT INTO items VALUES (1639, 'armorite-ore', 20, 30, 'collectibles', 'Rare ore that can be obtained on the Isle of Armor. Something good will happen if you give it to a collector on the Isle of Armor.');
INSERT INTO items VALUES (1640, 'mark-charm', 0, 0, 'gameplay', 'A mysterious and unique charm that increases the chance of finding a Pokémon with a mark.');
INSERT INTO items VALUES (1641, 'reins-of-unity--merge', 0, 0, 'unused', 'Reins that people presented to the king. They enhance Calyrex’s power over bountiful harvests and unite Calyrex with its beloved steed.');
INSERT INTO items VALUES (1642, 'reins-of-unity--split', 0, 0, 'unused', 'Reins that people presented to the king. They enable those who are connected to communicate with each other. The reins separate Calyrex and its beloved steed.');
INSERT INTO items VALUES (1643, 'galarica-wreath', 3000, 30, 'collectibles', 'A wreath made from woven-together Galarica Twigs. Placing it on the head of a Galarian Slowpoke makes the Pokémon very happy.');
INSERT INTO items VALUES (1644, 'legendary-clue-1', 0, 0, 'plot-advancement', 'A clue about the King of Bountiful Harvests. It’s written by Peony, and an old photo is attached to it.');
INSERT INTO items VALUES (1645, 'legendary-clue-2', 0, 0, 'plot-advancement', 'A clue about the legend of giants. It’s written by Peony and has unique drawings.');
INSERT INTO items VALUES (1646, 'legendary-clue-3', 0, 0, 'plot-advancement', 'A clue about the legend of bird Pokémon. It’s written by Peony and has a unique drawing.');
INSERT INTO items VALUES (1647, 'legendary-clue-question', 0, 0, 'plot-advancement', 'A mysterious clue that Peony seems to have dropped. There’s a photo attached to it showing a shining hole opening above the Max Lair.');
INSERT INTO items VALUES (1648, 'crown-pass', 0, 0, 'plot-advancement', 'A pass to go to the Crown Tundra. Show it to the rail staff at Wedgehurst Station.');
INSERT INTO items VALUES (1649, 'wooden-crown', 0, 0, 'plot-advancement', 'A mysterious object made of wood. Part of it seems to be chipped. Maybe it’s meant to be part of something.');
INSERT INTO items VALUES (1650, 'radiant-petal', 0, 0, 'plot-advancement', 'A single petal that the King of Bountiful Harvests gave you. It radiates faint light.');
INSERT INTO items VALUES (1651, 'white-mane-hair', 0, 0, 'plot-advancement', 'Mane hair that belonged to the King of Bountiful Harvests’ beloved steed, Glastrier. The hair is strong and very flexible.');
INSERT INTO items VALUES (1652, 'black-mane-hair', 0, 0, 'plot-advancement', 'Mane hair that belonged to the King of Bountiful Harvests’ beloved steed, Spectrier. The hair is very smooth to the touch.');
INSERT INTO items VALUES (1653, 'iceroot-carrot', 0, 0, 'plot-advancement', 'Produce that the King of Bountiful Harvests’ beloved steed likes to eat. It grew in a field covered in snow.');
INSERT INTO items VALUES (1654, 'shaderoot-carrot', 0, 0, 'plot-advancement', 'Produce that the King of Bountiful Harvests’ beloved steed likes to eat. It grew in a gloomy field.');
INSERT INTO items VALUES (1655, 'dynite-ore', 20, 30, 'collectibles', 'Mysterious ore that can be obtained in the Max Lair. Something good will happen if you give it to a collector in the Crown Tundra.');
INSERT INTO items VALUES (1656, 'carrot-seeds', 20, 0, 'plot-advancement', 'Seeds to plant in a field. The kind of carrot you’ll get is determined by which field you plant the seeds in.');
INSERT INTO items VALUES (1657, 'ability-patch', 20, 0, 'vitamins', 'A patch that allows a Pokémon with a regular Ability to have a rare Ability.');
INSERT INTO items VALUES (1658, 'reins-of-unity', 0, 0, 'plot-advancement', 'Cords that shine when you hold them up to the light. The people of old times presented these to the King of Bountiful Harvests to express their gratitude.');
